				<div class="elementor-element elementor-element-4e1470e elementor-icon-list--layout-traditional elementor-list-item-link-full_width elementor-widget elementor-widget-icon-list" data-id="4e1470e" data-element_type="widget" data-widget_type="icon-list.default">
				<div class="elementor-widget-container">
